(()=>{'use strict';if(window.__mbdKitchenApp)return;window.__mbdKitchenApp=true;
const K=globalThis.MBDKitchen,productionHost='madebydian-recipes-dian.vercel.app';if(!K)return;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID(),load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}};
const testMode=new URLSearchParams(location.search).get('kitchenTest')==='1'||location.hostname.endsWith('.vercel.app')&&location.hostname!==productionHost;
const expandedProducts=new Set(),failedIdeaImages=new Set();
let owner=null,client=null,revision=0,data=K.empty(),tab='week',week=K.monday(K.dayLocal()),round=0,lastDay=K.dayLocal(),search='',selectedOnly=false,archived=false,locationFilter='freezer',queue=[],chain=Promise.resolve(),syncBusy=false,loaded=false,authEpoch=0,toast='';
const scope=()=>testMode?'test':owner||'guest',key=()=>`mbd_kitchen_v1:${scope()}`,queueKey=()=>key()+':queue',statusKey=()=>key()+':status';
const recipes=()=>typeof state!=='undefined'?state.recipes:[],recipe=m=>recipes().find(r=>r.mdb===m||r.id===m),photo=m=>{const r=recipe(m),known=r&&K.inspirationPresentation(r);if(known)return known.photoURL;const candidate=r?.ownPhotoURL||r?.photoURL||r?.imageURL;if(candidate)try{const u=new URL(candidate,location.origin);if(['https:','http:'].includes(u.protocol)&&!u.username&&!u.password)return u.href}catch{}return '/assets/mbd-recipes-logo.svg'};
const prefs=()=>{const p=load('mbd_allergy_prefs_v1',{}),d=load('mbd_dislikes_v1',{});return {allergens:[...(p.selected||p.allergens||[]),...(p.custom||[])],dislikes:[...(d.standard||[]),...(d.custom||[]),...(d.week||[])]}};
function eligible(r){if(typeof MBDRecipeVisibility==='function'&&!MBDRecipeVisibility(r))return false;const p=prefs(),hay=K.norm([r.title,K.text(r.ingredients),K.text(r.steps)].join(' '));return !p.dislikes.some(x=>x&&hay.includes(K.norm(x)))}
function options(){return {eligible,ratings:typeof mbdRatingsRead==='function'?mbdRatingsRead():load('mbd_person_ratings_v1',{}),people:data.settings.recommendPeople||['Mama','Jake','Mace'],minRating:data.settings.minStars||0}}
function saveLocal(){localStorage.setItem(key(),JSON.stringify({revision,data}));localStorage.setItem(queueKey(),JSON.stringify(queue))}
function message(s){toast=s;const e=$('#kitchen-status');if(e)e.textContent=s;}
async function session(){if(!client)client=typeof weekCloud!=='undefined'&&weekCloud?weekCloud:window.supabase?.createClient('https://ywsdubincfabjhvjqkot.supabase.co','sb_publishable_sIPgFRcpRiszmq8vuWLkAg_K-C0gzfF');if(!client)return null;const {data:{session}}=await client.auth.getSession();return session}
async function api(action){const current=await session();if(!current?.access_token)throw Error('Log opnieuw in via Mijn account.');const response=await fetch('/api/app?kitchen=1',{method:action?'POST':'GET',headers:{Authorization:'Bearer '+current.access_token,...(action?{'Content-Type':'application/json'}:{})},...(action?{body:JSON.stringify({action})}:{})});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Online bewaren niet gelukt');return result}
async function flush(){if(syncBusy||!owner||testMode)return;syncBusy=true;const startedOwner=owner;try{while(queue.length&&owner===startedOwner){const action=queue[0],saved=await api(action);if(owner!==startedOwner)return;data=saved.data||K.empty();revision=saved.revision;queue.shift();saveLocal();render()}message('Opgeslagen en online teruggelezen.')}catch(e){message('Nog niet online opgeslagen: '+e.message+' Je actie blijft bewaard; kies Opnieuw synchroniseren.');saveLocal()}finally{syncBusy=false}}
async function send(type,payload){const action={id:id(),type,payload,at:new Date().toISOString()};try{K.apply(data,action);if(!owner||testMode){data=K.apply(data,action);saveLocal();message(testMode?'Testmodus: uitsluitend op dit apparaat bewaard.':'Op dit apparaat bewaard. Log in voor synchronisatie.');render();return true}queue.push(action);saveLocal();chain=chain.then(flush);await chain;return !queue.some(x=>x.id===action.id)}catch(e){message(e.message);return false}}
async function refreshAccount(){const epoch=++authEpoch;try{const s=await session();if(epoch!==authEpoch)return;const next=testMode?null:s?.user?.id||null;if(next!==owner||!loaded){owner=next;search='';const cached=load(key(),null);data=cached?.data||K.empty();revision=cached?.revision||0;queue=load(queueKey(),[]);loaded=true;render()}if(owner&&!testMode){const saved=await api();if(epoch!==authEpoch||next!==owner)return;data=saved.data||K.empty();revision=saved.revision;saveLocal();render();await flush()}}catch(e){message(e.message)}}
function modal(title,body){$('#kitchen-dialog')?.remove();const d=document.createElement('dialog');d.id='kitchen-dialog';d.className='mbd-kitchen';d.innerHTML='<div class="row" style="justify-content:space-between"><h2>'+esc(title)+'</h2><button type="button" data-close aria-label="Sluiten">×</button></div>'+body+'<p class="status" id="kitchen-dialog-status" aria-live="polite"></p>';document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();return d}
function form(title,fields,submit,label='Bewaar'){const d=modal(title,'<form id="k-form">'+fields+'<button class="primary" type="submit">'+esc(label)+'</button></form>');d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('[type=submit]');b.disabled=true;try{const result=await submit(new FormData(e.target),d);if(result!==false)d.close();else d.querySelector('#kitchen-dialog-status').textContent=toast}catch(err){d.querySelector('#kitchen-dialog-status').textContent=err.message}finally{b.disabled=false}};return d}
const input=(name,label,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;
const unitOptions=selected=>['portie','stuk','verpakking','g','kg','ml','l','fles','blik','zak'].map(x=>`<option ${x===selected?'selected':''}>${x}</option>`).join('');
function servings(){return data.settings.adults+data.settings.children*data.settings.childPortion}
function quantity(x){return x===null||x===undefined?'hoeveelheid controleren':String(Math.round(x*100)/100).replace('.',',')}
function recipeLines(r,people){const source=globalThis.MBDWeekCore?.basePeople(r.portions);const factor=r.portionPolicy==='keep_original_batch'||!source?1:people/source;return K.text(r.ingredients).split('\n').map(x=>x.trim()).filter(Boolean).map(x=>globalThis.MBDWeekCore?.scale(x,factor)||x)}
function daily(){const root=$('#kitchen-inspiration');if(!root)return;const previous=load(key()+':inspiration-history',{}),exclude=Object.entries(previous).filter(([d])=>d!==lastDay).flatMap(([,ids])=>ids);const list=K.inspirations(recipes(),lastDay,round,{...options(),exclude,presentable:r=>!failedIdeaImages.has(r.mdb)&&K.inspirationPresentation(r)});const signature=lastDay+'|'+round+'|'+list.map(r=>r.mdb+':'+r.title).join('|');if(root.dataset.signature===signature)return;root.dataset.signature=signature;previous[lastDay]=list.map(r=>r.mdb);for(const d of Object.keys(previous))if(d<K.shift(lastDay,-3))delete previous[d];localStorage.setItem(key()+':inspiration-history',JSON.stringify(previous));root.innerHTML='<div class="row inspiration-head"><div><div class="eyebrow">Voor vandaag</div><h2>Vier ideeën</h2></div><button data-other>Andere ideeën</button></div><div class="ideas">'+list.map(r=>`<article class="idea"><img loading="lazy" src="${esc(K.inspirationPresentation(r).photoURL)}" alt="" data-idea-image="${esc(r.mdb)}"><h3>${esc(r.title)}</h3><p class="muted">${esc(globalThis.MBDTimeCore?.bucket(r)||'Actieve tijd onbekend')}</p><button data-daily-view="${esc(r.id)}">Bekijk</button> <button data-daily-plan="${esc(r.id)}">+ Weekmenu</button></article>`).join('')+'</div>'+(list.length?'':'<p class="muted">Geen passende volledige recepten gevonden met je huidige voorkeuren.</p>');root.querySelectorAll('[data-idea-image]').forEach(img=>img.onerror=()=>{failedIdeaImages.add(img.dataset.ideaImage);daily()});root.querySelector('[data-other]').onclick=()=>{round++;daily()};root.querySelectorAll('[data-daily-plan]').forEach(b=>b.onclick=()=>placeRecipe(recipe(b.dataset.dailyPlan)));root.querySelectorAll('[data-daily-view]').forEach(b=>b.onclick=()=>showRecipeDetails(b.dataset.dailyView))}
function planFields(r,dateValue=K.dayLocal(),slot='dinner',item=null){return input('date','Dag',dateValue,'date','required')+`<label>Eetmoment<select name="slot">${K.slots.map(([v,t])=>`<option value="${v}" ${v===slot?'selected':''}>${t}</option>`).join('')}</select></label>`+input('servings','Gewenste receptporties',item?.servings||servings(),'number','min="0.25" max="100" step="0.25" required')+(r&&!globalThis.MBDWeekCore?.basePeople(r.portions)?'<p class="notice">De bron geeft geen persoonsporties. De oorspronkelijke batch blijft behouden; hoeveelheden worden niet automatisch omgerekend.</p>':'')}
function placeRecipe(r,d=K.dayLocal(),slot='dinner',extra={}){if(!r)return;form(r.title,planFields(r,d,slot)+`<label><input type="checkbox" name="mealprep" ${extra.mealprep?'checked':''}>Ook als mealprep tonen</label>`,async f=>send('plan_set',{id:id(),mdb:r.mdb||r.id,name:r.title,date:f.get('date'),slot:f.get('slot'),servings:Number(f.get('servings')),mealprep:f.has('mealprep')}),'Toevoegen')}
function freezerPlan(batch,d,slot){form(batch.name,input('date','Dag',d,'date','required')+`<label>Eetmoment<select name="slot">${K.slots.map(([k,t])=>`<option value="${k}" ${k===slot?'selected':''}>${t}</option>`).join('')}</select></label>`+input('batchQuantity','Reserveren ('+batch.unit+'), beschikbaar '+quantity(K.available(data,batch.id)),1,'number','min="0.001" step="any" required')+'<label>Aanvullende ingrediënten, bijvoorbeeld 200 g pasta<textarea name="extra" rows="3"></textarea></label><p class="muted">Reserveren boekt niets af. De voorraad vermindert pas nadat je Gebruik bevestigd kiest.</p>',async f=>send('plan_set',{id:id(),mdb:batch.recipeMDB||null,name:batch.name,date:f.get('date'),slot:f.get('slot'),servings:servings(),batchId:batch.id,batchQuantity:Number(f.get('batchQuantity')),extraIngredients:f.get('extra')}),'Reserveren')}
function picker(d,slot,mealprep=false){const suggested=K.suggestions(recipes(),d,slot,data,options());const collectionNames=typeof allCollections!=='undefined'?allCollections:[...new Set(recipes().flatMap(r=>globalThis.MBDTimeCore?.collections(r)||r.collections||[]))];const dlg=modal('Kies zelf een recept',`<p class="muted">${esc(d)} · ${esc(K.slots.find(([k])=>k===slot)?.[1])}. Suggesties zijn vrijblijvend.</p><input id="kp-search" type="search" placeholder="Zoek naam of ingrediënt"><label>Collectie<select id="kp-collection"><option value="">Alle bestaande collecties</option>${collectionNames.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><div id="kp-results"></div>`);const draw=()=>{const q=K.norm(dlg.querySelector('#kp-search').value),c=dlg.querySelector('#kp-collection').value;let list=q||c?recipes().filter(r=>eligible(r)&&K.text(r.ingredients)&&K.text(r.steps)&&(!q||K.norm(r.title+' '+K.text(r.ingredients)).includes(q))&&(!c||(globalThis.MBDTimeCore?.collections(r)||r.collections||[]).includes(c))):suggested;list=list.slice(0,60);dlg.querySelector('#kp-results').innerHTML=list.map((r,i)=>`<article class="picker-row">${r.mdb?`<img loading="lazy" src="${photo(r.mdb)}" alt="" onerror="this.hidden=true">`:''}<div><b>${esc(r.title)}</b><div class="muted">${r.batchId?'Uit diepvries · '+quantity(r.available)+' '+esc(r.unit)+' beschikbaar':esc(globalThis.MBDTimeCore?.bucket(r)||'Actieve tijd onbekend')}</div></div><button data-pick="${i}">Kies</button></article>`).join('');dlg.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const r=list[Number(b.dataset.pick)];dlg.close();if(r.batchId)freezerPlan(data.inventory[r.batchId],d,slot);else placeRecipe(r,d,slot,{mealprep})})};dlg.querySelector('#kp-search').oninput=draw;dlg.querySelector('#kp-collection').onchange=draw;draw()}
function renderWeek(){const target=$('#kitchen-content');const w=data.weeks[week]||{items:{}},rhythm={0:'Soep',1:'Wraps of taco’s',2:'Makkelijk · liefst uit de diepvries',3:'Ovenschotel',4:'Kindvriendelijk'};target.innerHTML=`<h2>Weekmenu</h2><div class="row"><label>Week van<input class="week-date" id="k-week" type="date" value="${week}"></label><button data-settings>Gezin & voorkeuren</button><button data-add-week-shopping>Boodschappen uit dit menu</button></div><p class="muted">Drie hoofdmaaltijden maken een dag compleet. Snacks zijn optioneel. Niets wordt zonder jouw keuze toegevoegd.</p>`+Array.from({length:7},(_,i)=>{const d=K.shift(week,i),day=new Intl.DateTimeFormat('nl-NL',{weekday:'long',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));return `<details class="card" ${d===K.dayLocal()?'open':''}><summary>${esc(day)} ${d.slice(8)}-${d.slice(5,7)} · ${K.complete(w,d)?'Hoofdmaaltijden compleet':'Nog hoofdmaaltijden kiezen'}</summary><p class="muted">${esc(rhythm[i]||'Vrij kiezen')} · je mag iedere keuze aanpassen.</p><div class="slots">${K.slots.map(([slot,name])=>{const item=w.items[d+'|'+slot],res=item&&data.reservations[item.id];return `<article class="slot"><b>${name}${K.main.includes(slot)?'':' (optioneel)'}</b>${item?`<p>${esc(item.name)}</p><p class="muted">${item.batchId?quantity(item.batchQuantity)+' '+esc(data.inventory[item.batchId]?.unit)+' uit diepvries':quantity(item.servings)+' gewenste receptporties'}${res?' · '+({reserved:'gereserveerd',used:'gebruik bevestigd',cancelled:'reservering opgeheven'}[res.status]):''}</p><div class="row">${item.mdb?`<button data-menu-view="${esc(item.mdb)}">Bekijk</button>`:''}<button data-move="${item.id}">Verplaats</button><button data-repeat="${item.id}">Herhaal</button><button data-plan="${d}|${slot}">Vervang</button><button data-remove="${item.id}">Verwijder</button>${res?.status==='reserved'?`<button data-use="${item.id}">Gebruik bevestigen</button>`:''}</div>`:`<p><button data-plan="${d}|${slot}">+ Kies ${name.toLowerCase()}</button></p>`}</article>`}).join('')}</div></details>`}).join('');const legacy=legacyItems();if(legacy.length&&!Object.keys(w.items).length)target.insertAdjacentHTML('beforeend','<button data-adopt>Neem mijn bestaande weekmenu bewust over</button>');target.querySelector('#k-week').onchange=e=>{week=K.monday(e.target.value);render()};target.querySelector('[data-settings]').onclick=settingsDialog;target.querySelector('[data-add-week-shopping]').onclick=()=>weekShopping(w);target.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>picker(...b.dataset.plan.split('|')));target.querySelectorAll('[data-menu-view]').forEach(b=>b.onclick=()=>{const r=recipe(b.dataset.menuView);if(r)showRecipeDetails(r.id)});target.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(confirm('Dit menu-item verwijderen? Een ongebruikte diepvriesreservering wordt opgeheven.'))send('plan_remove',{id:b.dataset.remove})});target.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{if(confirm('Heb je deze portie echt gebruikt? De fysieke voorraad wordt één keer verminderd.'))send('inventory_use',{itemId:b.dataset.use})});target.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const item=Object.values(w.items).find(x=>x.id===b.dataset.move);form('Verplaats '+item.name,planFields(recipe(item.mdb),item.date,item.slot,item),f=>send('plan_move',{id:item.id,date:f.get('date'),slot:f.get('slot')}),'Verplaatsen')});target.querySelectorAll('[data-repeat]').forEach(b=>b.onclick=()=>{const item=Object.values(w.items).find(x=>x.id===b.dataset.repeat);if(item.batchId)freezerPlan(data.inventory[item.batchId],K.shift(item.date,1),item.slot);else placeRecipe(recipe(item.mdb),K.shift(item.date,1),item.slot,{mealprep:item.mealprep})});target.querySelector('[data-adopt]')?.addEventListener('click',adoptLegacy)}
function legacyItems(){if(typeof state==='undefined')return [];const days=['Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag','Zondag'];return Object.entries(state.week||{}).map(([day,value])=>({i:days.indexOf(day),r:recipe(typeof value==='string'?value:value?.recipeId||value?.id||value?.mdb)})).filter(x=>x.i>=0&&x.r)}
async function adoptLegacy(){if(!confirm('Bestaande gerechten als avondeten in deze week overnemen? Je oorspronkelijke weekmenu en archief blijven behouden.'))return;for(const x of legacyItems())if(!await send('plan_set',{id:id(),mdb:x.r.mdb||x.r.id,name:x.r.title,date:K.shift(week,x.i),slot:'dinner',servings:servings()}))break}
function settingsDialog(){const p=data.settings;form('Gezin & aanbevelingen',`<div class="k-settings">${input('adults','Volwassenen',p.adults,'number','min="0" max="20" required')}${input('children','Kinderen',p.children,'number','min="0" max="20" required')}${input('childPortion','Receptportie per kind',p.childPortion,'number','min="0.25" max="2" step="0.25" required')}</div><p class="muted">Default telt ieder kind als één receptportie; pas dit zelf aan. Geen voedingsadvies op basis van leeftijd.</p><label>Minimale bestaande sterren<select name="minStars">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${n===(p.minStars||0)?'selected':''}>${n?n+' sterren':'Geen sterrenfilter'}</option>`).join('')}</select></label><p>Beoordelingen meewegen voor:</p>${['Mama','Jake','Mace','Gast'].map(person=>`<label><input type="checkbox" name="people" value="${person}" ${(p.recommendPeople||['Mama','Jake','Mace']).includes(person)?'checked':''}>${person}</label>`).join('')}<label><input type="checkbox" name="healthy" ${p.healthyAlternatives?'checked':''}>Gezondere alternatieven</label>`,f=>send('settings',{adults:Number(f.get('adults')),children:Number(f.get('children')),childPortion:Number(f.get('childPortion')),minStars:Number(f.get('minStars')),recommendPeople:f.getAll('people'),healthyAlternatives:f.has('healthy')}))}
function prep(){const target=$('#kitchen-content'),w=data.weeks[week]||{items:{}};target.innerHTML='<h2>Mealprep</h2><p class="muted">Maandag en donderdag één lunch en één snack voorstellen; jij kiest. Alle keuzes staan in hetzelfde weekmenu.</p>'+[0,3].map(n=>{const d=K.shift(week,n);return `<section class="card"><h3>${n===0?'Maandag':'Donderdag'} ${esc(d)}</h3>${[['lunch','Lunch'],['morning','Snack']].map(([slot,title])=>{const item=w.items[d+'|'+slot],r=item&&recipe(item.mdb);return `<article><h3>${title}</h3>${r?`<div class="picker-row"><img loading="lazy" src="${photo(r.mdb)}" alt="" onerror="this.hidden=true"><div><b>${esc(r.title)}</b><p class="muted">Bronopbrengst: ${esc(r.portions||'onbekend')} · actief: ${globalThis.MBDTimeCore?.activeMinutes(r)??'onbekend'} min</p></div></div><button data-prep-detail="${esc(r.id)}">Ingrediënten & bereiding</button> <button data-prep-freeze="${esc(r.id)}">Voeg porties toe aan diepvries</button>`:'<p>Nog niet gekozen.</p>'}<button data-prep-pick="${d}|${slot}">${r?'Ander voorstel kiezen':'Kies zelf'}</button></article>`}).join('')}</section>`}).join('')+`<section class="card"><h3>Gecombineerde voorbereiding</h3><p id="prep-time" class="muted"></p><label><input id="prep-parallel" type="checkbox">Gelijke ovenstand én beide gerechten passen tegelijk</label><button data-prep-combine>Bekijk gecombineerde ingrediënten</button><p class="muted">${esc(K.storageAdvice.text)}</p><a class="inline-link" target="_blank" rel="noopener" href="${K.storageAdvice.url}">Bewaaradvies Voedingscentrum</a></section>`;const selectedItems=Object.values(w.items).filter(x=>x.mealprep&&recipe(x.mdb));const selected=selectedItems.map(x=>recipe(x.mdb));const timing=()=>{const t=K.prepTime(selected,target.querySelector('#prep-parallel').checked);target.querySelector('#prep-time').textContent=!selected.length?'Kies eerst mealprep-recepten.':`Actief samen: ${t.active??'onbekend'} minuten. Totale preptijd: ${t.total??'nog onbekend'}${t.total!==null?' minuten':''}. ${t.parallelApplied?'Gelijke oventijden zijn gecombineerd.':'Ovenwerk niet als parallel bevestigd; ontbrekende tijden worden niet geschat.'}`};timing();target.querySelector('#prep-parallel').onchange=timing;target.querySelectorAll('[data-prep-pick]').forEach(b=>b.onclick=()=>picker(...b.dataset.prepPick.split('|'),true));target.querySelectorAll('[data-prep-detail]').forEach(b=>b.onclick=()=>showRecipeDetails(b.dataset.prepDetail));target.querySelectorAll('[data-prep-freeze]').forEach(b=>b.onclick=()=>inventoryForm(null,recipe(b.dataset.prepFreeze)));target.querySelector('[data-prep-combine]').onclick=()=>{const lines=K.combine(selectedItems.flatMap(x=>recipeLines(recipe(x.mdb),x.servings)));modal('Samen voorbereiden',`<p class="muted">Alleen gelijke ingrediënten met compatibele eenheden zijn opgeteld. Bereidingsstappen blijven per recept; snijwerk kan samen als dat logisch is.</p><ul>${lines.map(l=>`<li>${esc(quantity(l.quantity)+' '+l.unit+' '+l.name)}</li>`).join('')}</ul><button onclick="window.print()">Print</button>`)}}
function productForm(existing=null){const p=existing||{},newId=p.id||id();form(existing?'Product aanpassen':'Vast product toevoegen',input('name','Productnaam',p.name,'text','required maxlength="300"')+input('brand','Merk',p.brand)+input('package','Verpakking (leeg als onbekend)',p.package)+input('category','Categorie',p.category||'Overig')+input('variant','Voorkeursvariant',p.variant)+'<label>Bewaar eigen productinformatie<textarea name="nutrition" rows="3">'+esc(p.nutrition||'')+'</textarea></label>'+ input('ahURL','Exacte AH-productlink (optioneel)',p.ahURL,'url')+input('ahProductId','AH-productnummer (alleen indien bekend)',p.ahProductId),f=>send('product_save',{...p,id:newId,name:f.get('name'),brand:f.get('brand'),package:f.get('package'),category:f.get('category'),variant:f.get('variant'),nutrition:f.get('nutrition'),ahURL:f.get('ahURL'),ahProductId:f.get('ahProductId')}))}
function safeAlternative(p){const a=K.alternative(p,data.settings.healthyAlternatives);if(!a)return null;const choices=prefs();if(choices.allergens.some(x=>/gluten|tarwe/i.test(x))&&/volkoren/i.test(a.suggestion))return null;if(choices.dislikes.some(x=>K.norm(a.suggestion).includes(K.norm(x))))return null;return a}
function groceries(){const target=$('#kitchen-content'),w=data.shopping[week]||{manual:{},sources:{}},all=Object.values(data.products),filtered=all.filter(p=>(archived||!p.archived)&&(!selectedOnly||(w.manual?.[p.id]||0)>0)&&(!search||K.norm([p.name,p.brand,p.category,p.package].join(' ')).includes(K.norm(search))));const categories=[...new Set(filtered.map(p=>p.category||'Overig'))].sort((a,b)=>a.localeCompare(b,'nl'));target.innerHTML=`<h2>Weekboodschappen</h2><p class="muted">Je vaste lijst blijft bestaan. De weekhoeveelheid begint op nul; historie selecteert niets automatisch.</p><div class="row"><label>Week van<input class="week-date" type="date" id="shopping-week" value="${week}"></label><button data-product-new>+ Product</button><button data-product-import>Importeer producten / bestelling</button><button data-product-photo>Foto of schermopname</button><button data-product-link>AH-productlink</button></div><input id="product-search" type="search" placeholder="Zoek product, merk of categorie" value="${esc(search)}"><div class="row"><label><input id="selected-only" type="checkbox" ${selectedOnly?'checked':''}>Alleen geselecteerd</label><label><input id="show-archive" type="checkbox" ${archived?'checked':''}>Ook gearchiveerd</label></div><label class="health-control"><input id="healthy-alternatives" type="checkbox" ${data.settings.healthyAlternatives?'checked':''}>Gezondere alternatieven</label>${(load('mbd-extra-settings-v1',{}).products||[]).length?'<button data-legacy-products>Bestaande Mijn producten controleren en overnemen</button>':''}${typeof state!=='undefined'&&state.shoppingItems?.length?'<button data-legacy-shopping>Bestaande losse boodschappen controleren en overnemen</button>':''}<p class="muted">${all.length} vaste producten · ${K.shopping(data,week).length} actuele regels</p>`+categories.map(cat=>`<details class="card" data-product-category="${esc(cat)}" ${search||selectedOnly||expandedProducts.has(cat)?'open':''}><summary>${esc(cat)} (${filtered.filter(p=>p.category===cat).length})</summary>${filtered.filter(p=>p.category===cat).map(p=>{const alt=safeAlternative(p);return `<article class="product"><div><b>${esc(p.name)}</b><div class="muted">${esc([p.brand,p.package||'Verpakking controleren',p.variant].filter(Boolean).join(' · '))}${p.archived?' · gearchiveerd':''}</div><div class="small">${p.needsPackageCheck?'Verpakkingsgrootte nog controleren. ':''}${p.historicalQuantity!==null?'Bevestigd eerder besteld: '+quantity(p.historicalQuantity)+'. ':''}${p.observedOrderQuantity!==null&&p.observedOrderQuantity!==undefined?'Aangeleverd bestelaantal: '+quantity(p.observedOrderQuantity)+' (bestelstatus niet bevestigd).':''}</div>${alt?`<div class="alternative">${esc(alt.suggestion)}<br>${esc(alt.reason)} Je product blijft ongewijzigd.</div>`:''}<div class="row"><button data-edit-product="${p.id}">Aanpassen</button><button data-archive-product="${p.id}">${p.archived?'Herstellen':'Archiveren'}</button><button data-delete-product="${p.id}" class="danger-text">Verwijderen</button><a class="inline-link" target="_blank" rel="noopener" href="${esc(p.ahURL||'https://www.ah.nl/zoeken?query='+encodeURIComponent(p.name+' '+p.package))}">${p.ahURL?'AH-product':'Zoek bij AH'}</a></div></div><div class="quantity"><button data-amount="${p.id}" data-delta="-1" aria-label="Minder ${esc(p.name)}">−</button><b>${quantity(w.manual?.[p.id]||0)}</b><button data-amount="${p.id}" data-delta="1" aria-label="Meer ${esc(p.name)}">+</button></div></article>`}).join('')}</details>`).join('')+`<section class="card"><h3>Deze week nodig</h3><div>${K.shopping(data,week).map(l=>`<p><b>${esc(l.name)}</b> · ${esc(quantity(l.quantity)+' '+l.unit+' '+(l.package||''))}<br><span class="source">${esc([...new Set(l.sources)].join(' · '))}</span></p>`).join('')||'<p class="muted">Nog niets geselecteerd.</p>'}</div><button data-copy-shopping>Kopieer lijst voor AH</button> <a href="https://www.ah.nl/mijnlijst" target="_blank" rel="noopener" class="inline-link">Open mijn AH-winkelmandje</a><p class="notice">Er is geen bevestigde partnerkoppeling. Kopiëren of AH openen verstuurt geen bestelling. Rond je bestelling zelf bij AH af.</p><button data-purchase-confirm>Ik heb deze bestelling daadwerkelijk bevestigd</button><p class="muted">Alleen deze bevestiging wist de huidige weekselectie. Je vaste lijst en historie blijven bestaan. Bij annuleren blijven je aantallen staan.</p></section><details class="card"><summary>Bestelgeschiedenis (${Object.values(data.orders).length})</summary>${Object.values(data.orders).map(o=>`<p>${esc(o.deliveryDate||o.confirmedAt||'Datum onbekend')} · ${esc(o.status==='confirmed'?'bevestigd':o.status==='cancelled'?'geannuleerd':'status niet bevestigd')} · ${o.lines?.length||0} regels</p>`).join('')}</details>`;target.querySelectorAll('[data-product-category]').forEach(d=>d.querySelector('summary').onclick=e=>{e.preventDefault();d.open=!d.open;if(d.open)expandedProducts.add(d.dataset.productCategory);else expandedProducts.delete(d.dataset.productCategory)});target.querySelector('#product-search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;groceries();const el=target.querySelector('#product-search');el.focus();el.setSelectionRange(pos,pos)};target.querySelector('#selected-only').onchange=e=>{selectedOnly=e.target.checked;groceries()};target.querySelector('#show-archive').onchange=e=>{archived=e.target.checked;groceries()};target.querySelector('#healthy-alternatives').onchange=e=>send('settings',{healthyAlternatives:e.target.checked});target.querySelector('#shopping-week').onchange=e=>{week=K.monday(e.target.value);groceries()};target.querySelector('[data-legacy-products]')?.addEventListener('click',()=>importDialog((load('mbd-extra-settings-v1',{}).products||[]).map(p=>({...p,package:'',brand:'',category:'Overig',legacyRecord:p}))));target.querySelector('[data-legacy-shopping]')?.addEventListener('click',()=>{const r={title:'Bestaande losse boodschappen',mdb:'legacy',ingredients:(state.shoppingItems||[]).map(x=>typeof x==='string'?x:x.name||'').filter(Boolean).join('\n')};reviewShopping(r,1,'legacy-shopping')});target.querySelector('[data-product-new]').onclick=()=>productForm();target.querySelector('[data-product-import]').onclick=()=>importDialog();target.querySelector('[data-product-photo]').onclick=()=>photoDialog('catalog');target.querySelector('[data-product-link]').onclick=productLinkDialog;target.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>send('shopping_amount',{week,productId:b.dataset.amount,delta:Number(b.dataset.delta)}));target.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>productForm(data.products[b.dataset.editProduct]));target.querySelectorAll('[data-archive-product]').forEach(b=>b.onclick=()=>{const p=data.products[b.dataset.archiveProduct];send('product_archive',{id:p.id,archived:!p.archived})});target.querySelectorAll('[data-delete-product]').forEach(b=>b.onclick=()=>{if(confirm('Dit vaste product definitief verwijderen? Dit kan alleen zonder actuele weekselectie of voorraad. Je kunt ook archiveren.'))send('product_delete',{id:b.dataset.deleteProduct,confirmed:true})});target.querySelector('[data-copy-shopping]').onclick=async()=>{try{await navigator.clipboard.writeText(K.shopping(data,week).map(l=>`${quantity(l.quantity)} ${l.unit} ${l.name} ${l.package||''}`).join('\n'));message('Lijst gekopieerd. Nog niet verstuurd of besteld.')}catch{message('Kopiëren niet toegestaan; selecteer de regels handmatig.')}};target.querySelector('[data-purchase-confirm]').onclick=()=>{if(K.shopping(data,week).length&&confirm('Is je bestelling bij AH echt bevestigd? Alleen dan legen we deze weekselectie en bewaren we de bestelgeschiedenis.'))send('purchase_confirm',{week,orderId:id(),confirmed:true})}}
function inventoryForm(existing=null,r=null,proposal=null){const b=existing||proposal||{},batchId=b.id||id();form(existing?'Voorraad corrigeren':r?'Porties van '+r.title+' invriezen':'Voorraad toevoegen',input('name','Naam gerecht of product',b.name||r?.title,'text','required')+`<label>Locatie<select name="location">${[['freezer','Mijn diepvries'],['fridge','Koelkast'],['pantry','Voorraadkast'],['spices','Kruiden']].map(([v,t])=>`<option value="${v}" ${v===(b.location||locationFilter)?'selected':''}>${t}</option>`).join('')}</select></label>`+input('quantity','Aantal (leeg als onbekend)',b.quantity??'','number','min="0" step="any"')+`<label>Eenheid<select name="unit">${unitOptions(b.unit||'portie')}</select></label>`+`<label><input type="checkbox" name="uncertain" ${b.certainty==='uncertain'?'checked':''}>Voorraad controleren; aantal onzeker</label>`+input('frozenAt','Invries-/toevoegdatum',b.frozenAt||K.dayLocal(),'date')+input('expiresAt','Optionele bewaartermijn tot (niet raden)',b.expiresAt||'','date')+input('shelf','Lade of plaats (optioneel)',b.shelf||'')+(existing?input('reason','Reden correctie','','text','required'):'')+`<p class="muted">${esc(K.storageAdvice.text)}</p>`,f=>{const quantity=f.get('quantity')===''?0:Number(f.get('quantity'));const p={id:batchId,name:f.get('name'),quantity,unit:f.get('unit'),location:f.get('location'),certainty:f.has('uncertain')||f.get('quantity')===''?'uncertain':'confirmed',frozenAt:f.get('frozenAt')||null,expiresAt:f.get('expiresAt')||null,shelf:f.get('shelf'),recipeMDB:r?.mdb||b.recipeMDB||null,confirmed:true};return send(existing?'inventory_adjust':'inventory_add',existing?{...p,reason:f.get('reason')}:p)})}
function stock(){const target=$('#kitchen-content'),list=Object.values(data.inventory).filter(b=>b.location===locationFilter);target.innerHTML=`<h2>${locationFilter==='freezer'?'Mijn diepvries':'Voorraad in huis'}</h2><div class="tabs">${[['freezer','Diepvries'],['fridge','Koelkast'],['pantry','Voorraadkast'],['spices','Kruiden']].map(([v,t])=>`<button data-location="${v}" aria-pressed="${v===locationFilter}">${t}</button>`).join('')}</div><div class="row"><button data-stock-add>+ Handmatig toevoegen</button><button data-stock-photo>Foto met herkenningsvoorstel</button><button data-pantry-search>Zoek recepten met wat ik heb</button></div><p class="muted">Je hoeft niet eerst je hele keuken te inventariseren. Voeg producten toe wanneer je ze gebruikt. Reserveren is nog niet afboeken.</p>`+list.map(b=>`<article class="card"><div class="large-name">${esc(b.name)}</div><p>${b.certainty==='uncertain'?'Voorraad controleren':quantity(b.quantity)+' '+esc(b.unit)+' aanwezig · '+quantity(K.available(data,b.id))+' beschikbaar'}</p><p class="muted">${esc(b.frozenAt||'Datum onbekend')}${b.shelf?' · '+esc(b.shelf):''} · ${b.expiresAt?'indicatief tot '+esc(b.expiresAt):'bewaartermijn controleren'}</p><button data-stock-edit="${b.id}">Corrigeren</button>${b.location==='freezer'?` <button data-stock-plan="${b.id}">Reserveer in weekmenu</button>`:''}</article>`).join('')+(!list.length?'<p class="muted">Hier staat nog niets. Alleen bewust toegevoegde voorraad verschijnt hier.</p>':'')+'<details class="card"><summary>Voorraadmutaties en reserveringen</summary><div class="history" id="stock-history"></div><button data-history>Lees online mutatiehistorie</button></details>';target.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{locationFilter=b.dataset.location;stock()});target.querySelector('[data-stock-add]').onclick=()=>inventoryForm();target.querySelector('[data-stock-photo]').onclick=()=>photoDialog('inventory');target.querySelector('[data-pantry-search]').onclick=()=>pantrySearch();target.querySelectorAll('[data-stock-edit]').forEach(b=>b.onclick=()=>inventoryForm(data.inventory[b.dataset.stockEdit]));target.querySelectorAll('[data-stock-plan]').forEach(b=>b.onclick=()=>freezerPlan(data.inventory[b.dataset.stockPlan],K.shift(week,2),'dinner'));target.querySelector('#stock-history').innerHTML=Object.values(data.reservations).map(r=>`<p>${esc(data.inventory[r.batchId]?.name||'Gerecht')} · ${quantity(r.quantity)} · ${esc(r.status==='reserved'?'gereserveerd':r.status==='used'?'gebruikt':'geannuleerd')}</p>`).join('');target.querySelector('[data-history]').onclick=history}
async function history(){if(!owner||testMode){message('Online mutatiehistorie is beschikbaar na aanmelden. Lokale reserveringen staan hierboven.');return}try{const ss=await session(),r=await fetch('https://ywsdubincfabjhvjqkot.supabase.co/rest/v1/mbd_kitchen_actions?select=event,created_at&order=created_at.desc&limit=100',{headers:{apikey:'sb_publishable_sIPgFRcpRiszmq8vuWLkAg_K-C0gzfF',Authorization:'Bearer '+ss.access_token}});if(!r.ok)throw Error('Historie niet bereikbaar');const list=await r.json();$('#stock-history').innerHTML=list.filter(x=>/^inventory_|^plan_/.test(x.event.type)).map(x=>`<p>${esc(new Date(x.created_at).toLocaleString('nl-NL'))} · ${esc(({inventory_add:'voorraad toegevoegd',inventory_adjust:'voorraad gecorrigeerd',inventory_use:'gebruik bevestigd',plan_set:'menu/reservering gekozen',plan_remove:'menu verwijderd/reservering opgeheven',plan_move:'menu verplaatst'})[x.event.type]||x.event.type)}${x.event.stockChange?' · '+esc(x.event.stockChange.name)+': '+quantity(x.event.stockChange.from)+' → '+quantity(x.event.stockChange.to)+' '+esc(x.event.stockChange.unit):''}${x.event.payload?.reason?' · '+esc(x.event.payload.reason):''}</p>`).join('')||'<p>Nog geen voorraadmutaties.</p>'}catch(e){message(e.message)}}
function reviewShopping(r,people=servings(),sourceKey='recipe:'+r.mdb){const lines=recipeLines(r,people);form('Boodschappen uit '+r.title,`<p class="muted">Je hebt dit recept zelf gekozen. Controleer hoeveelheden, verpakkingen en voorraad. Onbekende bronporties worden niet omgerekend.</p><label>Benodigde ingrediënten (één per regel)<textarea name="lines" rows="10">${esc(lines.join('\n'))}</textarea></label><p class="muted">Voorraad wordt niet stilzwijgend als exact afgetrokken. Verwijder wat aantoonbaar in huis is; bij twijfel voorraad controleren.</p>`,async f=>{const ok=await send('shopping_source',{week,sourceKey,label:r.title,lines:String(f.get('lines')).split('\n').filter(x=>x.trim())});if(ok)open('shopping');return ok},'Voeg gecontroleerde ingrediënten toe')}
async function weekShopping(w){const items=Object.values(w.items||{});if(!items.length){message('Kies eerst zelf recepten in het weekmenu.');return}const previews=items.map(item=>{const r=recipe(item.mdb);return {item,lines:item.batchId?K.text(item.extraIngredients).split('\n').filter(Boolean):r?recipeLines(r,item.servings):[]}});const dlg=modal('Controleer weekboodschappen',`<p class="muted">Diepvriesgerechten leveren alleen hun aanvullende ingrediënten. Je kunt iedere lijst corrigeren vóór toevoegen.</p><form id="week-shopping-form">${previews.map(({item,lines},i)=>`<label>${esc(item.date+' · '+item.name)}<textarea rows="3" name="lines-${i}">${esc(lines.join('\n'))}</textarea></label>`).join('')}<button type="submit" class="primary">Deze selectie toevoegen</button></form>`);dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();const formData=new FormData(e.target),btn=e.target.querySelector('button');btn.disabled=true;try{for(let i=0;i<previews.length;i++){const {item}=previews[i],lines=String(formData.get('lines-'+i)).split('\n').filter(x=>x.trim());if(!await send('shopping_source',{week,sourceKey:'menu:'+item.id,label:item.name,lines}))return}dlg.close();open('shopping')}finally{btn.disabled=false}}}
function pantrySearch(names=[]){form('Koken met wat ik heb',`<label>Ingrediënten, gescheiden door komma’s<textarea name="names" rows="4">${esc(names.join(', '))}</textarea></label><p class="muted">Bestaande allergiefilters blijven gelden. Pas na het zelf kiezen van een recept voeg je ontbrekende boodschappen toe.</p><button type="button" id="pantry-photo">Foto van meerdere producten</button>`,f=>{const val=String(f.get('names'));setScreen('recipes');const field=$('#mbd-ingredients');if(field){field.value=val;field.dispatchEvent(new Event('input',{bubbles:true}))}else{$('#recipeSearch').value=val;$('#recipeSearch').dispatchEvent(new Event('input',{bubbles:true}))}return true},'Zoek passende recepten').querySelector('#pantry-photo').onclick=()=>{$('#kitchen-dialog').close();photoDialog('ingredients')}}
function importDialog(proposals=[]){const initial=proposals.map(p=>[p.name,p.brand||'',p.package||'',p.category||'Overig',p.quantity??''].join(' | ')).join('\n');const dlg=form('Controleer productimport',`<p class="muted">Eén product per regel: naam | merk | verpakking | categorie | waargenomen bestelaantal. Onbekende velden leeg laten. Productlinks mogen als extra veld achteraan. Deze aantallen selecteren geen weekboodschappen.</p><label>Correcteerbare producten<textarea name="rows" rows="10" required>${esc(initial)}</textarea></label><label>Historische bestelling<select name="status"><option value="none">Alleen vaste producten toevoegen</option><option value="unconfirmed">Bestelling, status nog niet bevestigd</option><option value="confirmed">Werkelijk bevestigde bestelling</option><option value="cancelled">Geannuleerde bestelling — niet meetellen</option></select></label>${input('orderDate','Besteldatum indien bekend','','date')}<p class="notice">Hetzelfde product en dezelfde verpakking worden niet dubbel toegevoegd. Een andere verpakking blijft apart. Folders, speelgoedboekjes en promotionele hangers worden overgeslagen.</p>`,async(f,d)=>{const parsed=String(f.get('rows')).split('\n').map(line=>{const [name,brand,pack,category,amount,ahURL]=line.split('|').map(x=>x.trim());const original=proposals.find(p=>K.norm(p.name)===K.norm(name))||{};return {...original,id:id(),name,brand,package:pack,category:category||'Overig',quantity:amount!==''&&amount!==undefined?Number(amount.replace(',','.')):null,ahURL:ahURL||original.ahURL||null}}).filter(p=>p.name&&!/tijdschrift|promotiefolder|speelgoedboek|disney.?hanger/i.test(p.name));if(parsed.some(p=>p.quantity!==null&&(!Number.isFinite(p.quantity)||p.quantity<0)))throw Error('Controleer de bestelaantallen');const status=f.get('status');if(status==='cancelled'){message('Geannuleerde bestelling telt niet mee; geen producten of aantallen geïmporteerd.');return true}const seen=new Set(),newRows=[];let duplicates=0;for(const p of parsed){const k=K.productKey(p);if(seen.has(k)||Object.values(data.products).some(x=>K.sameProduct(x,p)))duplicates++;else{newRows.push(p);seen.add(k)}}if(!confirm(`${newRows.length} nieuwe vaste producten; ${duplicates} bestaande/dubbele regels behouden. Weekhoeveelheden blijven nul. Importeren?`))return false;if(newRows.length&&!await send('products_import',{confirmed:true,products:newRows}))return false;if(status!=='none'){const lines=parsed.map(p=>({productId:Object.values(data.products).find(x=>K.sameProduct(x,p))?.id,name:p.name,package:p.package,quantity:p.quantity}));if(status==='confirmed'&&lines.some(l=>l.quantity===null))throw Error('Bevestigde bestelgeschiedenis vereist een gecontroleerd aantal per product');if(!await send('order_import',{confirmed:true,id:id(),status,orderedAt:f.get('orderDate')||null,lines}))return false}message(`${newRows.length} producten geïmporteerd; ${duplicates} dubbele regels niet opnieuw toegevoegd.`);return true},'Controleer en importeer');return dlg}
function productLinkDialog(){form('AH-productlink controleren',input('url','Originele AH-productlink','','url','required'),async f=>{const url=String(f.get('url'));if(!/^https:\/\/(?:www\.)?ah\.nl\/producten\/product\/wi\d+/.test(url))throw Error('Gebruik een originele AH-productlink.');let proposal={ahURL:url,ahProductId:url.match(/\/wi(\d+)/)?.[1]||null};if(owner&&!testMode){const ss=await session();const res=await fetch('/api/app?kitchen=product-link',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+ss.access_token},body:JSON.stringify({url})});const result=await res.json();if(!res.ok)throw Error(result.error);proposal={...proposal,...result.product};message(result.note)}setTimeout(()=>productForm({...proposal,id:id(),name:proposal.name||'',package:proposal.package||'',brand:proposal.brand||'',category:'Overig'}),0);return true},'Lees voorstel')}
function photoDialog(destination){const dlg=modal('Herkennen en zelf corrigeren',`<p class="muted">Alleen zichtbare productinformatie wordt voorgesteld. Niets wordt zonder jouw bevestiging opgeslagen. Voor een schermopname kies je zelf een leesbaar frame.</p><input id="k-photo-file" type="file" accept="image/*,video/*"><div id="k-photo-preview"></div><button id="k-photo-read" disabled>Lees dit beeld</button>`);let image=null,video=null,objectURL=null;const reader=dlg.querySelector('#k-photo-read');dlg.addEventListener('close',()=>{if(objectURL)URL.revokeObjectURL(objectURL)});dlg.querySelector('#k-photo-file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;image=null;video=null;reader.disabled=true;const preview=dlg.querySelector('#k-photo-preview');preview.replaceChildren();if(f.type.startsWith('video/')){objectURL=URL.createObjectURL(f);video=document.createElement('video');video.controls=true;video.playsInline=true;video.className='video-preview';video.src=objectURL;preview.append(video);video.onloadeddata=()=>{reader.disabled=false;reader.textContent='Lees het huidige videoframe'}}else{if(f.size>3000000){dlg.querySelector('#kitchen-dialog-status').textContent='Gebruik een afbeelding kleiner dan 3 MB.';return}image=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)});reader.disabled=false}};reader.onclick=async()=>{reader.disabled=true;try{if(video){const canvas=document.createElement('canvas');const factor=Math.min(1,1280/video.videoWidth);canvas.width=video.videoWidth*factor;canvas.height=video.videoHeight*factor;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);image=canvas.toDataURL('image/jpeg',.86)}const ss=await session();if(!ss?.access_token)throw Error('Log in voor fotoherkenning. Handmatig toevoegen werkt ook zonder herkenning.');const result=await fetch('/api/recipes/recognize-photo',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+ss.access_token},body:JSON.stringify({hint:'kitchen_products',image})});const recognized=await result.json();if(!result.ok)throw Error(recognized.error||'Herkenning niet gelukt');dlg.close();if(destination==='ingredients')pantrySearch(recognized.products.map(p=>p.name));else if(destination==='inventory'){form('Corrigeer herkende voorraad',`<label>Herkende productnamen (één per regel)<textarea name="names" rows="7">${esc(recognized.products.map(p=>p.name).join('\n'))}</textarea></label><p class="muted">Aantallen worden niet geraden. Iedere gekozen naam wordt daarna met locatie en hoeveelheid bevestigd.</p>`,f=>{const names=String(f.get('names')).split('\n').filter(x=>x.trim());localStorage.setItem(key()+':recognition-pending',JSON.stringify(names));message(names.length+' namen bewaard voor handmatige voorraadcontrole.');setTimeout(()=>nextRecognizedStock(),0);return true},'Controleer voorraad één voor één')}else importDialog(recognized.products)}catch(err){dlg.querySelector('#kitchen-dialog-status').textContent=err.message}finally{reader.disabled=false}}}
function nextRecognizedStock(){const list=load(key()+':recognition-pending',[]);if(!list.length)return;const name=list[0],dlg=inventoryForm(null,null,{name});setTimeout(()=>{const active=$('#kitchen-dialog');if(active){active.addEventListener('close',()=>{const remaining=load(key()+':recognition-pending',[]);remaining.shift();localStorage.setItem(key()+':recognition-pending',JSON.stringify(remaining));if(remaining.length)setTimeout(nextRecognizedStock,0)},{once:true})}},0)}
function open(next){tab=next;setScreen('week');render();$('#kitchen-root')?.scrollIntoView({behavior:'smooth',block:'start'})}
function render(){const root=$('#kitchen-root');if(!root)return;root.querySelector('#kitchen-mode').textContent=testMode?'Testmodus: lokale testgegevens, geen productieschrijfacties.':owner?'Privé opgeslagen bij je account. Wijzigingen synchroniseren na teruglezen.':'Alleen op dit apparaat. Log in via Mijn account voor synchronisatie.';root.querySelectorAll('[data-kitchen-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kitchenTab===tab)));if(tab==='week')renderWeek();else if(tab==='prep')prep();else if(tab==='stock')stock();else groceries();message(toast);daily()}
function collectionsTools(){const host=$('#collectionOverview');if(!host||$('#kitchen-collection-search'))return;const bar=document.createElement('div');bar.className='mbd-kitchen';bar.innerHTML='<label>Zoek bestaande collectie<input id="kitchen-collection-search" type="search" placeholder="Collectienaam"></label><div id="kitchen-favorite-collections" class="row"></div>';host.before(bar);const details=document.createElement('details');details.open=true;details.innerHTML='<summary>Collecties tonen / inklappen</summary>';host.before(details);details.append(host);const draw=()=>{const q=K.norm($('#kitchen-collection-search').value);if(q)details.open=true;host.querySelectorAll('.collection-card').forEach(card=>card.hidden=!!q&&!K.norm(card.textContent).includes(q));const favorites=load('mbd_favorite_collections_v1',[]);let controls=$('#kitchen-favorite-toggle');if(!controls){controls=document.createElement('button');controls.id='kitchen-favorite-toggle';controls.textContent='Snelkeuze kiezen';bar.append(controls);controls.onclick=()=>{const names=typeof COLLECTIONS!=='undefined'?COLLECTIONS.map(x=>x[0]):[];const dlg=form('Veelgebruikte collecties',names.map(n=>'<label><input type="checkbox" name="names" value="'+esc(n)+'" '+(load('mbd_favorite_collections_v1',[]).includes(n)?'checked':'')+'>'+esc(n)+'</label>').join(''),f=>{localStorage.setItem('mbd_favorite_collections_v1',JSON.stringify(f.getAll('names')));draw();return true});}}$('#kitchen-favorite-collections').innerHTML=favorites.map(c=>`<button data-favorite-open="${esc(c)}">★ ${esc(c)}</button>`).join('');bar.querySelectorAll('[data-favorite-open]').forEach(b=>b.onclick=()=>setScreen('recipes',b.dataset.favoriteOpen))};$('#kitchen-collection-search').oninput=draw;new MutationObserver(draw).observe(host,{childList:true});host.addEventListener('contextmenu',e=>{const card=e.target.closest('.collection-card');if(!card)return;e.preventDefault();const name=typeof COLLECTIONS!=='undefined'?COLLECTIONS[Number(card.dataset.collectionIndex)]?.[0]:card.querySelector('b')?.textContent;if(!name)return;const favorites=load('mbd_favorite_collections_v1',[]);localStorage.setItem('mbd_favorite_collections_v1',JSON.stringify(favorites.includes(name)?favorites.filter(x=>x!==name):[...favorites,name]));draw()});const hint=document.createElement('p');hint.className='muted';hint.textContent='Houd een collectie ingedrukt om deze als snelkeuze te bewaren. Je recepten en indeling blijven gelijk.';bar.append(hint);draw()}
function attachDetailAction(){const body=$('#modalRecipeBody');if(!body||body.querySelector('[data-kitchen-recipe-shopping]'))return;const r=recipe(body.dataset.recipeId);if(!r)return;const button=document.createElement('button');button.dataset.kitchenRecipeShopping='1';button.textContent='Naar mijn weekboodschappen';button.onclick=()=>reviewShopping(r);body.append(button)}
function boot(){if($('#kitchen-root'))return;const screen=$('[data-screen="week"]');if(!screen)return;const legacy=document.createElement('details');legacy.className='mbd-legacy-week';legacy.id='kitchen-legacy-week';legacy.innerHTML='<summary>Bestaand weekmenu en eerdere archieven</summary>';for(const child of [...screen.children])legacy.append(child);screen.append(legacy);const root=document.createElement('section');root.id='kitchen-root';root.className='mbd-kitchen';root.innerHTML='<div class="card"><div class="eyebrow">Mijn keuken</div><p id="kitchen-mode" class="muted"></p><nav class="tabs" aria-label="Keukenonderdelen">'+[['week','Weekmenu'],['prep','Mealprep'],['stock','Diepvries & voorraad'],['shopping','Weekboodschappen']].map(([v,t])=>`<button data-kitchen-tab="${v}">${t}</button>`).join('')+'</nav><div class="row"><a href="/account.html">Mijn account</a><button id="kitchen-sync">Opnieuw synchroniseren</button></div><p id="kitchen-status" class="status" aria-live="polite"></p></div><div id="kitchen-content"></div>';screen.prepend(root);root.querySelectorAll('[data-kitchen-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.kitchenTab;render()});root.querySelector('#kitchen-sync').onclick=refreshAccount;const groceryShortcut=document.createElement('div');groceryShortcut.className='mbd-kitchen kitchen-shortcuts';groceryShortcut.innerHTML='<button id="kitchen-open-shopping" class="primary" type="button">🛒 Boodschappen</button>';$('.topbar')?.after(groceryShortcut);groceryShortcut.querySelector('button').onclick=()=>open('shopping');const inspiration=document.createElement('section');inspiration.id='kitchen-inspiration';inspiration.className='mbd-kitchen card';$('[data-screen="recipes"] .search-wrap')?.before(inspiration);const settings=$('[data-screen="settings"]');const shortcuts=document.createElement('section');shortcuts.className='mbd-kitchen card';shortcuts.innerHTML='<h2>Mijn keuken</h2><div class="row"><button data-open="shopping">Weekboodschappen</button><button data-open="stock">Mijn diepvries</button><button data-open="prep">Mealprep</button><button data-family>Gezin & aanbevelingen</button></div>';settings?.prepend(shortcuts);shortcuts.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>open(b.dataset.open));shortcuts.querySelector('[data-family]').onclick=settingsDialog;document.addEventListener('click',e=>{const b=e.target.closest?.('#mbdSuggestWeekBtn,#mbd-week-auto,#mbd-open-products');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.id==='mbd-open-products'){open('shopping');return}if(b.id==='shoppingBtn')weekShopping(data.weeks[week]||{items:{}});else{open('week');message('Kies per dag zelf een voorstel; er is niets automatisch ingevuld.')}},true);window.addEventListener('mbd:recipes-rendered',()=>{daily();attachDetailAction()});let detailTimer;new MutationObserver(()=>{clearTimeout(detailTimer);detailTimer=setTimeout(attachDetailAction,30)}).observe($('#modalRecipeBody'),{childList:true});collectionsTools();render();refreshAccount();session().then(()=>client?.auth.onAuthStateChange?.(()=>setTimeout(refreshAccount,0)));window.addEventListener('online',refreshAccount);window.addEventListener('storage',e=>{if(e.key===key())refreshAccount()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshAccount()});setInterval(()=>{const now=K.dayLocal();if(now!==lastDay){lastDay=now;round=0;daily()}},60000);window.MBDKitchenApp={open,refresh:refreshAccount,getSnapshot:()=>({owner,revision,data:cloneData(),pending:queue.length}),send,planRecipe:placeRecipe,photoDialog,inventoryForm,productForm};function cloneData(){return structuredClone(data)}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
